it('P1: chuyên viên vượt hạn mức không được duyệt hồ sơ do người khác tạo', async () => {
    const dx = await taoDeXuat('HM-2026-8001', 600_000_000, 'hung');
    const res = await app.inject({
      method: 'POST',
      url: `/api/de-xuat/${dx.id}/duyet`,
      headers: { 'x-user': 'lan' },
    });
    expect(res.statusCode).toBe(403);
    expect(JSON.stringify(res.json())).toMatch(/500[.,]?000[.,]?000/);

    const ds = await app.inject({ method: 'GET', url: '/api/de-xuat' });
    const found = ds.json().find((d: { id: number }) => d.id === dx.id);
    expect(found.trang_thai).toBe('cho_duyet');
  });

